import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static BigInteger factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }

    public static BigInteger A(int n, int k) {
        return factorial(n).divide(factorial(n - k));
    }

    public static void run() {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        String[] parts = line.trim().split("\\s+");
        int n = Integer.parseInt(parts[0]);
        int mod = Integer.parseInt(parts[1]);
        if (n == 1) {
            System.out.println(0);
            return;
        }
        int[] current_z = {1};
        long result_sum = 0;
        for (int i = 2; i <= n; i++) {
            int size = i * i / 2;
            int[] new_z = new int[size];
            for (int j = 0; j < current_z.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (current_z[j] > 0) {
                        int index = i - k - 1 + j;
                        if (index >= 0 && index < new_z.length) {
                            new_z[index] += current_z[j];
                        }
                    }
                }
            }
            int[] prefix = new int[current_z.length + 1];
            for (int w = current_z.length - 1; w >= 0; w--) {
                prefix[w] = (prefix[w + 1] + current_z[w]) % mod;
            }
            int[] e_arr = new int[prefix.length];
            int[] f_arr = new int[prefix.length];
            for (int w = 0; w < prefix.length - 1; w++) {
                e_arr[w + 1] = (e_arr[w] + prefix[w]) % mod;
                long tempF = (long)f_arr[w] - (long)w * prefix[w];
                f_arr[w + 1] = (int)((tempF % mod + mod) % mod);
            }
            long local_sum = 0;
            for (int jj = 0; jj < current_z.length; jj++) {
                int L = jj + 2;
                int R = Math.min(current_z.length - 1, i + jj);
                long ccc = 0;
                if (R >= L) {
                    long e_diff = (e_arr[R + 1] - e_arr[L]) % mod;
                    long f_diff = (f_arr[R + 1] - f_arr[L]) % mod;
                    ccc = ((e_diff * (long)(i + 1 + jj)) % mod + f_diff) % mod;
                }
                long contribution = (ccc * current_z[jj]) % mod;
                local_sum = (local_sum + contribution) % mod;
            }
            BigInteger aVal = A(n, n - i);
            long aMod = aVal.mod(BigInteger.valueOf(mod)).longValue();
            result_sum = (result_sum + local_sum + (local_sum * aMod) % mod) % mod;
            current_z = new_z;
        }
        System.out.println(result_sum % mod);
        scanner.close();
    }

    public static void main(String[] args) {
        run();
    }
}
